def merge_keyword_and_vector_results(keyword_ids: list[str], vector_ids: list[str], k: int = 60) -> list[str]:
    # Combine exact keyword matches (BM25) + meaning matches (vectors)
    scores: dict[str, float] = {}
    for rank, doc_id in enumerate(keyword_ids, start=1):
        scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    for rank, doc_id in enumerate(vector_ids, start=1):
        scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores, key=lambda d: scores[d], reverse=True)[:20]

